import {countChars} from '../precheck/engine.mjs';
export function selectedDetectionSections(parsed,ids){return parsed.sections.filter(s=>!s.excluded&&ids.includes(s.id));}
export function detectionChars(parsed,ids){return selectedDetectionSections(parsed,ids).reduce((n,s)=>n+s.paragraphs.reduce((m,p)=>m+countChars(p.text),0),0);}
export function selectDetectionReports(reports,{query='',project='all'}={}){const q=query.trim().toLowerCase();return reports.filter(r=>(project==='all'||(project==='none'?!r.projectId:r.projectId===project))&&(!q||String(r.title||'').toLowerCase().includes(q))).slice().sort((a,b)=>(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0));}
export function validateDetectionSource(v){const title=String(v.title||'').trim(),text=String(v.text||'').trim();if(!title||title.length>200)throw Error('请填写不超过 200 字符的来源标题。');const chars=countChars(text);if(chars<16||chars>20000||text.length>100000)throw Error('对照正文需包含 16–20,000 个有效字符，原文最多 100,000 字符。');let url=String(v.url||'').trim();if(url){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw Error();url=u.href;}catch{throw Error('来源 URL 仅支持有效 HTTP / HTTPS 地址。');}}const doi=String(v.doi||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'');if(doi&&!/^10\.\d{4,9}\/\S+$/i.test(doi))throw Error('DOI 格式无效，或留空；当前不联网核验。');const year=String(v.year||'').trim();if(year&&!/^\d{4}$/.test(year))throw Error('年份应为四位数字或留空。');return {title,text,url:url||null,doi:doi||null,year:year?Number(year):null,authors:String(v.authors||'').split(/[,，、]/).map(x=>x.trim()).filter(Boolean),provider:'用户添加的本地材料',kind:'user',license:'用户确认有权进行本地比对'};}
